function Result({ data }) {
  const score = data.score || 0;
  const scoreClass =
    score >= 75 ? "score-good" : score >= 50 ? "score-warn" : "score-bad";

  // matchedSkills may be missing on older resumes — fallback to data.skills
  const matched = (data.matchedSkills && data.matchedSkills.length) ? data.matchedSkills : (data.skills || []);

  return (
    <div className="result-card">
      <div className="result-header">
        <h3>Result</h3>
        <div className={`score-badge ${scoreClass}`}>{Math.round(score)}%</div>
      </div>

      <div className="result-body">
        <div className="tags">
          <strong>Matched Skills:</strong>
          {matched && matched.length ? (
            matched.map((s, i) => (
              <span key={i} className="skill-chip">
                {s}
              </span>
            ))
          ) : (
            <span className="muted"> No matched skills</span>
          )}
        </div>

        <div className="tags">
          <strong>Missing Skills:</strong>
          {data.missingSkills && data.missingSkills.length ? (
            data.missingSkills.map((s, i) => (
              <span key={i} className="skill-chip missing">
                {s}
              </span>
            ))
          ) : (
            <span className="muted"> None</span>
          )}
        </div>

        <p>
          <strong>Interview Status:</strong> {data.interviewStatus}
        </p>

        {data.jobSkills && data.jobSkills.length > 0 && (
          <p><strong>Job Skills:</strong> {data.jobSkills.join(', ')}</p>
        )}

        {data.createdAt && (
          <p className="muted">Uploaded: {new Date(data.createdAt).toLocaleString()}</p>
        )}
      </div>
    </div>
  );
}
export default Result;
